richlistitem[is="calendar-invitations-richlistitem"] {
  padding: 6px 7px;
  min-block-size: 25px;
  border-block-end: 1px dotted #808080;

  @media (-moz-overlay-scrollbars) {
    padding-inline-end: env(scrollbar-inline-size);
  }
}

.content-box {
  overflow: hidden;
}

.calendar-invitations-richlistitem-title {
  font-weight: bold;
  white-space: break-spaces;
}

